# Usage

## Totals

```js
import { computeTotal } from '../src/checkout.js';

computeTotal([{ price: 10, qty: 2 }], { discountCode: 'SAVE10' });
```

## Shipping Cost

Calculate shipping based on order subtotal:

```js
import { shippingCost } from '../src/shipping.js';

// Empty cart - free shipping
shippingCost(0); // 0

// Small orders - flat rate
shippingCost(50); // 5.99
shippingCost(99.99); // 5.99

// Orders $100+ - free shipping
shippingCost(100); // 0
shippingCost(150); // 0
```

## Checkout Summary

Generate a complete checkout summary with subtotal, shipping, and total:

```js
import { checkoutSummary } from '../src/summary.js';

// With items and discount code
checkoutSummary(
  [
    { price: 29.99, qty: 1 },
    { price: 15.50, qty: 2 }
  ],
  { discountCode: 'SAVE10' }
);

// Returns:
// {
//   subtotal: 60.99,
//   total: 54.891,      // after discount
//   shipping: 5.99,     // flat rate for orders under $100
//   grandTotal: 60.891  // total + shipping
// }

// Without discount code
checkoutSummary([{ price: 150, qty: 1 }]);

// Returns:
// {
//   subtotal: 150,
//   total: 150,
//   shipping: 0,        // free shipping at $100+
//   grandTotal: 150
// }
```
